// swift-tools-version: 5.9

import PackageDescription

// The Swift target must be named `flutter_opendroneid`: the Dart FFI bindings
// look classes up by their Objective-C runtime names
// (`_TtC19flutter_opendroneid...`), which embed the Swift module name. It has to
// match `ffiModuleName` in `pigeon/messages.dart`.
//
// SwiftPM does not allow Swift and Objective-C in one target, so the FFIgen
// trampolines generated by Pigeon (`Messages.g.m`) live in their own target.
let package = Package(
  name: "flutter_opendroneid",
  platforms: [
    .iOS("13.0")
  ],
  products: [
    .library(name: "flutter-opendroneid", targets: ["flutter_opendroneid"])
  ],
  dependencies: [
    // Resolved by Flutter's SwiftPM integration in the ephemeral packages directory.
    .package(name: "FlutterFramework", path: "../FlutterFramework")
  ],
  targets: [
    .target(
      name: "flutter_opendroneid_objc_gen",
      dependencies: [],
      publicHeadersPath: "."
    ),
    .target(
      name: "flutter_opendroneid",
      dependencies: [
        "flutter_opendroneid_objc_gen",
        .product(name: "FlutterFramework", package: "FlutterFramework"),
      ]
    ),
  ]
)
